import XCTest

final class OpenFirstPostTests: XCTestCase {
    func testOpenFirstFollowingPost() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let cancel = springboard.alerts.buttons["Cancel"]
        if cancel.waitForExistence(timeout: 3) {
            cancel.tap()
        }

        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.launch()

        let postText = app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "Mochi napping")).firstMatch
        if postText.waitForExistence(timeout: 30) {
            postText.tap()
        } else {
            app.windows.firstMatch.coordinate(withNormalizedOffset: CGVector(dx: 0.25, dy: 0.297)).tap()
        }
        sleep(4)
    }
}

